package com.bank.treasury.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;

@Entity
@Table(name = "treasury_bonds")
public class TreasuryBond {
    @Id @Column(name = "bond_id") private String bondId;
    private String name;
    @Column(name = "face_value") private BigDecimal faceValue;
    @Column(name = "coupon_rate") private BigDecimal couponRate;
    @Column(name = "maturity_date") private LocalDate maturityDate;
    private String status;

    protected TreasuryBond() {}

    public void mature() { this.status = "MATURED"; }

    public String getBondId() { return bondId; }
    public String getName() { return name; }
    public BigDecimal getFaceValue() { return faceValue; }
    public String getStatus() { return status; }
}
