// Shows what Spring auto-configures for PlatformTransactionManager
package com.bank.treasury.config;

import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;

@Configuration
@Slf4j
public class TxManagerConfig {

    /**
     * Spring Boot auto-configures JpaTransactionManager when spring-data-jpa is on classpath.
     * You can see it here:
     *
     * INTERNAL CHAIN:
     * 1. @Transactional on method → CGLIB proxy intercepts
     * 2. Proxy → TransactionInterceptor (MethodInterceptor)
     * 3. TransactionInterceptor → reads @Transactional attributes
     * 4. TransactionInterceptor → calls TransactionAspectSupport.invokeWithinTransaction()
     * 5. TransactionAspectSupport → selects PlatformTransactionManager
     *    (by qualifier name, or @Primary, or sole candidate)
     * 6. PlatformTransactionManager.getTransaction(definition)
     *    → DataSourceUtils.getConnection(dataSource)
     *    → connection.setAutoCommit(false)
     *    → TransactionSynchronizationManager.bindResource(dataSource, connectionHolder)
     * 7. Real method executes (all repos use thread-bound connection)
     * 8a. Success → manager.commit() → connection.commit()
     * 8b. RuntimeException → manager.rollback() → connection.rollback()
     * 9. TransactionSynchronizationManager.unbindResource()
     * 10. Connection returned to HikariCP pool
     */
    @Bean
    CommandLineRunner logTxManager(PlatformTransactionManager txManager) {
        return args -> {
            log.info("═══ TRANSACTION MANAGER INTERNALS ═══");
            log.info("PlatformTransactionManager: {}", txManager.getClass().getSimpleName());
            log.info("  → JpaTransactionManager (auto-configured by Spring Boot)");
            log.info("  → Wraps: DataSource (HikariCP) + EntityManagerFactory (Hibernate)");
            log.info("");
            log.info("CALL CHAIN when @Transactional method is called:");
            log.info("  1. CGLIB Proxy intercepts the call");
            log.info("  2. TransactionInterceptor reads @Transactional attributes");
            log.info("  3. TransactionAspectSupport.invokeWithinTransaction()");
            log.info("  4. PlatformTransactionManager.getTransaction()");
            log.info("     → HikariCP.getConnection()");
            log.info("     → connection.setAutoCommit(false)");
            log.info("     → TransactionSynchronizationManager.bindResource(ds, conn)");
            log.info("  5. REAL method executes (repos use thread-bound connection)");
            log.info("  6a. Success → manager.commit() → connection.commit()");
            log.info("  6b. RuntimeException → manager.rollback() → connection.rollback()");
            log.info("  7. unbindResource() → connection returned to pool");
            log.info("═══════════════════════════════════════");
        };
    }
}
