package com.bank.treasury.controller;

import com.bank.treasury.model.TreasuryBond;
import com.bank.treasury.service.TreasuryService;
import lombok.RequiredArgsConstructor;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDate;
import java.util.List;

@RestController
@RequestMapping("/api/v1/treasury")
@RequiredArgsConstructor
public class TreasuryController {

    private final TreasuryService treasuryService;

    @GetMapping("/maturing")
    public List<TreasuryBond> maturing(
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate before) {
        return treasuryService.findMaturingBonds(before);
    }

    @PostMapping("/{bondId}/mature")
    public String mature(@PathVariable String bondId) {
        treasuryService.matureBond(bondId);
        return "MATURED";
    }
}
